  -- speaking: c2-publish-an-unfinished-street-noise-map (C2)
  if exists (select 1 from public.speaking_prompts where product_id = v_product_speaking and language_id = v_en_id and slug = 'c2-publish-an-unfinished-street-noise-map') then
